  const handleDownloadInvoicePDF = async () => {
    if (!selectedQuoteDetail) {
      toast.error("Quotation details not found.");
      return;
    }

    const baseURL = process.env.REACT_APP_BACKEND_URL || "";
    const req = selectedQuoteDetail.productRequest || {};

    // Robust iOS detection including iPhone, iPad, iPod, iPadOS (MacIntel with touch), and Google Search / iOS Webviews
    const isIOS =
      /iPad|iPhone|iPod/i.test(navigator.userAgent) ||
      (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1) ||
      (/Macintosh/i.test(navigator.userAgent) && navigator.maxTouchPoints > 1);

    const identifier =
      selectedQuoteDetail.quotationId ||
      selectedQuoteDetail._id ||
      req.orderId ||
      req._id ||
      req.selectedQuotationId;

    // On iOS (especially Google Search App / GSA, iOS Safari, Chrome for iOS):
    // Direct HTTP GET navigation triggers native WebKit/iOS PDF viewing and downloading without JavaScript blob/popup blocking restrictions.
    if (isIOS && identifier) {
      toast.success("Opening Confirmation Letter PDF...", { id: "seller-invoice-pdf-toast" });
      window.location.href = `${BASE_URL}/api/quotation/${encodeURIComponent(identifier)}/pdf`;
      return;
    }

    try {
      toast.loading("Generating PDF...", { id: "seller-invoice-pdf-toast" });

      const delOption = req.selectedDeliveryOption || selectedQuoteDetail.deliveryOption || "Standard Delivery";
      const isStorePickup = delOption.toLowerCase().includes("store pick") || delOption.toLowerCase().includes("pickup");
      const rawDelTime = req.selectedEstimatedDeliveryTime || selectedQuoteDetail.estimatedDeliveryTime || "";
      const delTime = isStorePickup ? "" : rawDelTime;
      const delCharges = req.selectedDeliveryCharges !== undefined && req.selectedDeliveryCharges !== null
        ? Number(req.selectedDeliveryCharges)
        : Number(selectedQuoteDetail.deliveryCharges || 0);

      const totalMrp = Number(selectedQuoteDetail.totalMrp || 0);
      const totalDiscount = Number(selectedQuoteDetail.totalDiscount || 0);
      const platformFee = Number(selectedQuoteDetail.platformFee || 0);
      const calcTotal = (totalMrp - totalDiscount) + platformFee + delCharges;
      const finalPriceToDisplay = selectedQuoteDetail.totalPrice > 0 ? Number(selectedQuoteDetail.totalPrice) : calcTotal;

      const quotedItems = (selectedQuoteDetail.items || [])
        .filter(item => !shouldHideItem(item))
        .map(item => ({
          productName: getItemDisplayName(item),
          brand: item.brand,
          quantity: Number(item.quantity || 1),
          mrp: Number(item.mrp || 0),
          discount: item.discount !== undefined ? item.discount : 0,
          discountType: item.discountType || "Price",
          prescriptionChecked: item.prescriptionChecked === "Yes" || item.prescriptionChecked === true,
          finalPrice: Number(item.finalPrice || 0),
        }));

      const seller = selectedQuoteDetail.sellerId || {};
      const sellerBasic = seller.basicInformation || {};
      const sellerContact = seller.contactInformation || {};
      const sellerAddressStr = [
        sellerBasic.houseNo,
        sellerBasic.addressLine1,
        sellerBasic.addressLine2,
        sellerBasic.city,
        sellerBasic.state,
        sellerBasic.pincode
      ].filter(Boolean).join(", ");

      const buyerAddrObj = req.deliveryAddress || req.location || req.buyerAddress;
      const bHouseNo = buyerAddrObj?.houseNo || req.houseNo || req.buyerId?.houseNo || "";
      const bLandmark = buyerAddrObj?.landmark || req.landmark || req.buyerId?.landmark || "";

      let fullBuyerAddress = "";
      if (typeof buyerAddrObj === "string") {
        const parts = [];
        if (bHouseNo && !buyerAddrObj.toLowerCase().startsWith(bHouseNo.toLowerCase())) {
          parts.push(bHouseNo);
        }
        parts.push(buyerAddrObj);
        if (bLandmark && !buyerAddrObj.toLowerCase().includes(bLandmark.toLowerCase())) {
          parts.push(`Landmark: ${bLandmark}`);
        }
        fullBuyerAddress = parts.filter(Boolean).join(", ");
      } else if (buyerAddrObj) {
        const streetAddr = buyerAddrObj.address || buyerAddrObj.addressLine1 || buyerAddrObj.street || "";
        const parts = [];
        if (bHouseNo && !streetAddr.toLowerCase().startsWith(bHouseNo.toLowerCase())) {
          parts.push(bHouseNo);
        }
        if (streetAddr) {
          parts.push(streetAddr);
        }
        if (bLandmark && !streetAddr.toLowerCase().includes(bLandmark.toLowerCase())) {
          parts.push(`Landmark: ${bLandmark}`);
        }
        if (buyerAddrObj.city && !streetAddr.toLowerCase().includes(buyerAddrObj.city.toLowerCase())) {
          parts.push(buyerAddrObj.city);
        }
        if (buyerAddrObj.state && !streetAddr.toLowerCase().includes(buyerAddrObj.state.toLowerCase())) {
          parts.push(buyerAddrObj.state);
        }
        if ((buyerAddrObj.pincode || buyerAddrObj.zipcode) && !streetAddr.includes(String(buyerAddrObj.pincode || buyerAddrObj.zipcode))) {
          parts.push(buyerAddrObj.pincode || buyerAddrObj.zipcode);
        }
        fullBuyerAddress = parts.filter(Boolean).join(", ");
      }

      const distVal = req.distanceDisplay || req.deliveryDistanceDisplay || (req.distance !== undefined && req.distance !== null ? (typeof req.distance === 'number' ? (req.distance < 1 ? `${Math.round(req.distance * 1000)} m` : `${req.distance.toFixed(1)} km`) : String(req.distance)) : null) || "N/A";

      const reqDate = formatDateDMY(req.createdAt || selectedQuoteDetail.createdAt);

      const payload = {
        orderId: req.orderId || selectedQuoteDetail.quotationId || selectedQuoteDetail._id || "Quotation",
        quotationId: selectedQuoteDetail.quotationId,
        requestDate: reqDate,
        productRequestDate: reqDate,
        date: reqDate,
        sellerName: sellerBasic.shopName || seller.name || "Seller",
        sellerLogo:
          sellerBasic.logo ||
          seller.logo ||
          selectedQuoteDetail.sellerLogo ||
          selectedQuoteDetail.logo ||
          "",
        sellerAddress: sellerAddressStr || "N/A",
        sellerPhone: sellerContact.Mobileprimary || seller.phone || "",
        sellerEmail: seller.email || "",
        buyerName: req.deliveryAddress?.name || "Customer",
        buyerAddress: fullBuyerAddress || "N/A",
        buyerPhone: req.deliveryAddress?.phone || "",
        deliveryOption: delOption,
        estimatedDeliveryTime: delTime,
        items: quotedItems,
        totalMrp: totalMrp,
        totalDiscount: totalDiscount,
        deliveryCharges: delCharges,
        platformFee: platformFee,
        totalPrice: finalPriceToDisplay,
      };

      const response = await fetch(`${BASE_URL}/api/quotation/generate-pdf`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        throw new Error(`Server returned ${response.status}: ${response.statusText}`);
      }

      const blob = await response.blob();
      const pdfBlob = new Blob([blob], { type: "application/pdf" });
      const filename = `Confirmation_Letter_${payload.orderId}.pdf`;

      if (isIOS) {
        const reader = new FileReader();
        reader.onloadend = () => {
          window.location.href = reader.result;
          toast.success("Confirmation letter opened! Tap Share → Save to Files to save.", {
            id: "seller-invoice-pdf-toast",
          });
        };
        reader.onerror = () => {
          const blobUrl = window.URL.createObjectURL(pdfBlob);
          window.location.href = blobUrl;
          toast.success("Confirmation letter opened! Tap Share → Save to Files to save.", {
            id: "seller-invoice-pdf-toast",
          });
        };
        reader.readAsDataURL(pdfBlob);
      } else {
        // Android / Desktop Windows / Mac / Linux
        const blobUrl = window.URL.createObjectURL(pdfBlob);
        const link = document.createElement("a");

        link.href = blobUrl;
        link.download = filename;

        document.body.appendChild(link);
        link.click();
        link.remove();

        toast.success("Confirmation Letter PDF downloaded successfully!", { id: "seller-invoice-pdf-toast" });

        setTimeout(() => {
          window.URL.revokeObjectURL(blobUrl);
        }, 5000);
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to generate PDF", { id: "seller-invoice-pdf-toast" });
    }
  };

  const fetchRecentRequestsRef = useRef(fetchRecentRequests);
