  const handleExpire = (reqId) => {
    if (!reqId) return;
    setRequests((prev) => prev.filter((r) => r.id !== reqId && r._id !== reqId));
    const socket = getSocket();
    if (socket) {
      socket.emit("requestExpired", { requestId: reqId });
    }
  };

  // Real-time WebSocket support for dashboard
  useEffect(() => {
    const socket = getSocket();
    const sellerId = localStorage.getItem("sellerId");
    if (sellerId) {
      joinSellerRoom(sellerId);
    }

    const handleUpdate = () => {
      fetchRecentRequestsRef.current(true);
      fetchActiveOrdersRef.current(true);
      fetchDashboardStatsRef.current();
    };

    const handleRequestExpired = (data) => {
      if (data && data.requestId) {
        setRequests((prev) => prev.filter((req) => req.id !== data.requestId && req._id !== data.requestId));
      }
      handleUpdate();
    };

    socket.on("newProductRequest", handleUpdate);
    socket.on("requestUpdated", handleUpdate);
    socket.on("quotationSubmitted", handleUpdate);
    socket.on("newOrder", handleUpdate);
    socket.on("orderUpdated", handleUpdate);
    socket.on("requestExpired", handleRequestExpired);

    return () => {
      socket.off("newProductRequest", handleUpdate);
      socket.off("requestUpdated", handleUpdate);
      socket.off("quotationSubmitted", handleUpdate);
      socket.off("newOrder", handleUpdate);
      socket.off("orderUpdated", handleUpdate);
      socket.off("requestExpired", handleRequestExpired);
    };
  }, []);

  const filteredRequests = requests;

