import React from "react";
import { useNavigate } from "react-router-dom";
import SellerDashboardLayout from "../../components/E-Commerce/SellerDashboard/SellerDashboardLayout";
import DashboardTab from "../../components/E-Commerce/SellerDashboard/DashboardTab";
import RequestsTab from "../../components/E-Commerce/SellerDashboard/RequestsTab";
import ProductsTab from "../../components/E-Commerce/SellerDashboard/ProductsTab";
import InventoryTab from "../../components/E-Commerce/SellerDashboard/InventoryTab";
import OrdersTab from "../../components/E-Commerce/SellerDashboard/OrdersTab";
import PrescriptionTab from "../../components/E-Commerce/SellerDashboard/PrescriptionTab";
import DeliveryTab from "../../components/E-Commerce/SellerDashboard/DeliveryTab";
import ReportsTab from "../../components/E-Commerce/SellerDashboard/ReportsTab";
import NotificationsTab from "../../components/E-Commerce/SellerDashboard/NotificationsTab";
import ProfileTab from "../../components/E-Commerce/SellerDashboard/ProfileTab";
import SettingsTab from "../../components/E-Commerce/SellerDashboard/SettingsTab";
import ActivitiesTab from "../../components/E-Commerce/SellerDashboard/ActivitiesTab";

const SellerDashboardPage = ({ activeTab = "dashboard" }) => {
  const navigate = useNavigate();

  const setActiveTab = (tab) => {
    if (tab === "dashboard") {
      navigate("/seller-dashboard");
    } else {
      navigate(`/seller-dashboard/${tab}`);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case "dashboard":
        return <DashboardTab setActiveTab={setActiveTab} />;
      case "incoming-requests":
      case "submitted-proposals":
      case "expired-requests":
        return <RequestsTab activeSub={activeTab} />;
      case "all-products":
      case "add-product":
        return <ProductsTab activeSub={activeTab} />;
      case "inventory-list":
      case "stock-alerts":
        return <InventoryTab activeSub={activeTab} />;
      case "active-orders":
      case "completed-orders":
      case "cancelled-orders":
        return <OrdersTab activeSub={activeTab} />;
      case "prescription-requests":
        return <PrescriptionTab />;
      case "delivery-zones":
      case "delivery-settings":
        return <DeliveryTab activeSub={activeTab} />;
      case "reports":
        return <ReportsTab />;
      case "notifications":
        return <NotificationsTab />;
      case "profile":
        return <ProfileTab />;
      case "settings":
        return <SettingsTab />;
      case "activities":
        return <ActivitiesTab />;
      default:
        return <DashboardTab setActiveTab={setActiveTab} />;
    }
  };

  return (
    <SellerDashboardLayout activeTab={activeTab}>
      <div className="dashboard-body__content mt-3 px-md-4 px-3">
        {renderContent()}
      </div>
    </SellerDashboardLayout>
  );
};

export default SellerDashboardPage;
