import React, { useState } from "react";
import toast from "react-hot-toast";
import { FiLock, FiMail, FiPhone, FiBell, FiDollarSign, FiCheck, FiX, FiShield, FiInfo, FiKey, FiEye, FiEyeOff } from "react-icons/fi";

const SettingsTab = () => {
  const [accountForm, setAccountForm] = useState({
    email: "contact@apexpharmacy.com",
    mobile: "9876543210",
    oldPassword: "",
    newPassword: "",
    confirmPassword: "",
  });

  const [notificationPrefs, setNotificationPrefs] = useState({
    emailAlerts: true,
    smsAlerts: true,
  });

  const [paymentPrefs, setPaymentPrefs] = useState({
    onlinePayments: true,
    cod: true,
  });

  const validatePassword = (pwd) => {
    return {
      length: pwd.length > 8,
      lowercase: /[a-z]/.test(pwd),
      uppercase: /[A-Z]/.test(pwd),
      digit: /[0-9]/.test(pwd),
      special: /[!@#$%^&*(),.?":{}|<>]/.test(pwd),
    };
  };

  const passwordChecks = validatePassword(accountForm.newPassword || "");
  const isPasswordValid = Object.values(passwordChecks).every(Boolean);

  const handleSaveAccount = (e) => {
    e.preventDefault();
    if (accountForm.newPassword) {
      if (!isPasswordValid) {
        toast.error("Please fulfill all password validation requirements.");
        return;
      }
      if (accountForm.newPassword !== accountForm.confirmPassword) {
        toast.error("New passwords do not match!");
        return;
      }
    }
    toast.success("Account settings updated successfully.");
    setAccountForm((prev) => ({
      ...prev,
      oldPassword: "",
      newPassword: "",
      confirmPassword: "",
    }));
  };

  const handleSavePreferences = (e) => {
    e.preventDefault();
    toast.success("Preferences saved successfully.");
  };

  return (
    <div className="settings-tab animate-fade-in">
      <h3 style={{ fontSize: "22px", fontWeight: "800", color: "#0F172A", marginBottom: "20px" }}>
        System Settings
      </h3>

      <div className="row g-4">
        
        {/* Account Details Form & Security Tips (2-Column Layout) */}
        <div className="col-12">
          <div className="row g-4">
            {/* Left Column: Change Password Form */}
            <div className="col-lg-7">
              <div className="dashboard-card p-4 h-100" style={{ borderRadius: "16px", border: "1px solid #E2E8F0" }}>
                <div className="d-flex align-items-center gap-3 mb-4">
                  <div
                    className="d-flex align-items-center justify-content-center flex-shrink-0"
                    style={{
                      width: "48px",
                      height: "48px",
                      borderRadius: "50%",
                      backgroundColor: "#F3E8FF",
                      color: "#A847F0"
                    }}
                  >
                    <FiLock size={22} />
                  </div>
                  <div>
                    <h5 className="mb-1" style={{ fontWeight: "800", color: "#0F172A", fontSize: "18px" }}>
                      Change Your Password
                    </h5>
                    <p className="mb-0 text-muted" style={{ fontSize: "13px" }}>
                      Ensure your account stays protected with a strong password.
                    </p>
                  </div>
                </div>

                <form onSubmit={handleSaveAccount}>
                  <div className="d-flex flex-column gap-3">
                    <div>
                      <label className="form-label fw-bold text-dark mb-1.5" style={{ fontSize: "13.5px" }}>Current Password</label>
                      <div className="position-relative">
                        <span className="position-absolute top-50 translate-middle-y ms-3 text-muted">
                          <FiKey size={18} />
                        </span>
                        <input
                          type="password"
                          placeholder="Enter current password"
                          className="form-control border shadow-none"
                          style={{ paddingLeft: "42px", paddingRight: "42px", height: "48px", borderRadius: "8px", fontSize: "14px" }}
                          value={accountForm.oldPassword}
                          onChange={(e) => setAccountForm({ ...accountForm, oldPassword: e.target.value })}
                        />
                      </div>
                    </div>

                    <div>
                      <label className="form-label fw-bold text-dark mb-1.5" style={{ fontSize: "13.5px" }}>New Password</label>
                      <div className="position-relative">
                        <span className="position-absolute top-50 translate-middle-y ms-3 text-muted">
                          <FiLock size={18} />
                        </span>
                        <input
                          type="password"
                          placeholder="Enter new password"
                          className="form-control border shadow-none"
                          style={{ paddingLeft: "42px", paddingRight: "42px", height: "48px", borderRadius: "8px", fontSize: "14px" }}
                          value={accountForm.newPassword}
                          onChange={(e) => setAccountForm({ ...accountForm, newPassword: e.target.value })}
                        />
                      </div>
                    </div>

                    <div>
                      <label className="form-label fw-bold text-dark mb-1.5" style={{ fontSize: "13.5px" }}>Confirm New Password</label>
                      <div className="position-relative">
                        <span className="position-absolute top-50 translate-middle-y ms-3 text-muted">
                          <FiLock size={18} />
                        </span>
                        <input
                          type="password"
                          placeholder="Confirm new password"
                          className="form-control border shadow-none"
                          style={{ paddingLeft: "42px", paddingRight: "42px", height: "48px", borderRadius: "8px", fontSize: "14px" }}
                          value={accountForm.confirmPassword}
                          onChange={(e) => setAccountForm({ ...accountForm, confirmPassword: e.target.value })}
                        />
                      </div>
                    </div>

                    <div className="pt-2">
                      <button
                        type="submit"
                        className="btn text-white w-100 py-3 border-0 d-flex align-items-center justify-content-center gap-2"
                        style={{
                          background: "linear-gradient(90deg, #28B3FF, #5C51FF)",
                          borderRadius: "10px",
                          fontWeight: "700",
                          fontSize: "15px",
                          boxShadow: "0 4px 12px rgba(92, 81, 255, 0.25)"
                        }}
                      >
                        <FiLock size={18} />
                        Update Security Credentials
                      </button>
                    </div>
                  </div>
                </form>
              </div>
            </div>

            {/* Right Column: Security Tips & Password Requirements */}
            <div className="col-lg-5">
              <div
                className="p-4 h-100 d-flex flex-column justify-content-between"
                style={{
                  backgroundColor: "#F8FAFC",
                  border: "1px solid #E2E8F0",
                  borderRadius: "16px"
                }}
              >
                <div>
                  <div className="d-flex align-items-center gap-2 mb-3">
                    <FiShield size={24} style={{ color: "#059669" }} />
                    <h5 className="mb-0" style={{ fontWeight: "800", color: "#0F172A", fontSize: "18px" }}>
                      Security Tips
                    </h5>
                  </div>

                  {/* Password Strength Progress Bar */}
                  {accountForm.newPassword && (() => {
                    const passedCount = Object.values(passwordChecks).filter(Boolean).length;
                    const percentage = (passedCount / 5) * 100;
                    const strengthLabel =
                      passedCount === 0 ? "" :
                      passedCount <= 2 ? "Weak" :
                      passedCount <= 4 ? "Medium" : "Strong";

                    const strengthColor =
                      passedCount <= 2 ? "#EF4444" :
                      passedCount <= 4 ? "#F59E0B" : "#10B981";

                    return (
                      <div style={{ marginBottom: "18px", padding: "12px 16px", backgroundColor: "#FFFFFF", border: "1px solid #E2E8F0", borderRadius: "10px" }}>
                        <div className="d-flex justify-content-between align-items-center mb-1.5">
                          <span style={{ fontSize: "12px", fontWeight: "600", color: "#64748B" }}>Password Strength</span>
                          <span style={{ fontSize: "12px", fontWeight: "700", color: strengthColor }}>{strengthLabel}</span>
                        </div>
                        <div className="progress" style={{ height: "6px", backgroundColor: "#E2E8F0", borderRadius: "10px", overflow: "hidden" }}>
                          <div className="progress-bar" style={{ width: `${percentage}%`, backgroundColor: strengthColor, transition: "all 0.3s ease" }}></div>
                        </div>
                      </div>
                    );
                  })()}

                  {/* Requirements Checklist */}
                  <div style={{ display: "flex", flexDirection: "column", gap: "12px", marginBottom: "20px" }}>
                    {[
                      { key: "length", label: "Length should be greater than 8" },
                      { key: "lowercase", label: "Include at least one lowercase letter (a-z)." },
                      { key: "uppercase", label: "Include at least one uppercase letter (A-Z)." },
                      { key: "digit", label: "Atleast one number" },
                      { key: "special", label: "Atleast one special character" },
                    ].map((rule) => {
                      const passed = passwordChecks[rule.key];
                      return (
                        <div key={rule.key} style={{ display: "flex", alignItems: "flex-start", gap: "12px" }}>
                          <span
                            style={{
                              width: "20px",
                              height: "20px",
                              minWidth: "20px",
                              minHeight: "20px",
                              borderRadius: "50%",
                              backgroundColor: passed ? "#10B981" : "#E2E8F0",
                              color: passed ? "#FFFFFF" : "#94A3B8",
                              display: "inline-flex",
                              alignItems: "center",
                              justifyContent: "center",
                              marginTop: "2px",
                              flexShrink: 0,
                              transition: "all 0.2s ease"
                            }}
                          >
                            {passed ? <FiCheck size={12} /> : <FiX size={12} />}
                          </span>
                          <span
                            style={{
                              fontSize: "13px",
                              fontWeight: passed ? "600" : "500",
                              color: passed ? "#10B981" : "#475569",
                              lineHeight: "1.4"
                            }}
                          >
                            {rule.label}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* Pro Tip Highlight Box */}
                <div
                  className="p-3 mt-3"
                  style={{
                    backgroundColor: "#FFFBEB",
                    borderLeft: "4px solid #F59E0B",
                    borderRadius: "6px"
                  }}
                >
                  <div className="d-flex align-items-center gap-1.5 mb-1" style={{ color: "#D97706", fontWeight: "700", fontSize: "13px" }}>
                    <FiInfo size={16} /> Pro Tip
                  </div>
                  <p className="mb-0" style={{ fontSize: "12px", color: "#78350F", lineHeight: "1.4" }}>
                    Consider using a password manager to generate and store complex, unique passwords for all your online accounts.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Configurations Side Cards */}
        <div className="col-lg-6">
          <div className="d-flex flex-column gap-4">
            
            {/* Preferences form */}
            <div className="dashboard-card p-4">
              <div className="d-flex align-items-center gap-2 mb-3 border-bottom pb-2">
                <FiBell size={18} color="#A847F0" />
                <h5 className="font-16 fw-800 text-heading mb-0">Notification Preferences</h5>
              </div>

              <div className="d-flex flex-column gap-3 mb-3">
                
                <div className="d-flex justify-content-between align-items-center">
                  <div>
                    <strong className="text-heading d-block font-14">Email Alerts</strong>
                    <span className="text-muted small">Send order status and request emails</span>
                  </div>
                  <div className="form-check form-switch fs-5">
                    <input
                      className="form-check-input shadow-none cursor-pointer"
                      type="checkbox"
                      checked={notificationPrefs.emailAlerts}
                      onChange={(e) => setNotificationPrefs({ ...notificationPrefs, emailAlerts: e.target.checked })}
                    />
                  </div>
                </div>

                <div className="d-flex justify-content-between align-items-center">
                  <div>
                    <strong className="text-heading d-block font-14">SMS Notifications</strong>
                    <span className="text-muted small">Deliver text notifications for urgent proposals</span>
                  </div>
                  <div className="form-check form-switch fs-5">
                    <input
                      className="form-check-input shadow-none cursor-pointer"
                      type="checkbox"
                      checked={notificationPrefs.smsAlerts}
                      onChange={(e) => setNotificationPrefs({ ...notificationPrefs, smsAlerts: e.target.checked })}
                    />
                  </div>
                </div>

              </div>
              <div className="text-end">
                <button onClick={handleSavePreferences} className="btn btn-light pill px-4 btn-sm">
                  Save Alerts Preferences
                </button>
              </div>
            </div>

            {/* Payment switches card */}
            <div className="dashboard-card p-4">
              <div className="d-flex align-items-center gap-2 mb-3 border-bottom pb-2">
                <FiDollarSign size={18} color="#10B981" />
                <h5 className="font-16 fw-800 text-heading mb-0">Accepted Payment Methods</h5>
              </div>

              <div className="d-flex flex-column gap-3 mb-3">
                
                <div className="d-flex justify-content-between align-items-center">
                  <div>
                    <strong className="text-heading d-block font-14">Online Pre-paid Payments</strong>
                    <span className="text-muted small">Accept UPI, Credit/Debit Cards, NetBanking</span>
                  </div>
                  <div className="form-check form-switch fs-5">
                    <input
                      className="form-check-input shadow-none cursor-pointer"
                      type="checkbox"
                      checked={paymentPrefs.onlinePayments}
                      onChange={(e) => setPaymentPrefs({ ...paymentPrefs, onlinePayments: e.target.checked })}
                    />
                  </div>
                </div>

                <div className="d-flex justify-content-between align-items-center">
                  <div>
                    <strong className="text-heading d-block font-14">Cash on Delivery (COD)</strong>
                    <span className="text-muted small">Allow payment during physical parcel handover</span>
                  </div>
                  <div className="form-check form-switch fs-5">
                    <input
                      className="form-check-input shadow-none cursor-pointer"
                      type="checkbox"
                      checked={paymentPrefs.cod}
                      onChange={(e) => setPaymentPrefs({ ...paymentPrefs, cod: e.target.checked })}
                    />
                  </div>
                </div>

              </div>
              <div className="text-end">
                <button onClick={handleSavePreferences} className="btn btn-light pill px-4 btn-sm">
                  Apply Payment Toggles
                </button>
              </div>
            </div>

          </div>
        </div>

      </div>
    </div>
  );
};

export default SettingsTab;
